for loc, pairs in T.items():
    h = en
    for a, b in pairs:
        if a not in h: print(loc, "MISSING", a[:70])
        h = h.replace(a, b)
    if loc == "es": h = h.replace('<h2 id="dispatch-title">Dispatch a sample job</h2>', '<h2 id="dispatch-title">Despacha un trabajo de ejemplo</h2>')
    # paths: assets one level up, the page's own address
    for a in ['href="style.css"', 'src="home.js"', 'href="fonts/', 'href="media/', 'poster="media/', 'data-src="media/', 'href="mark.svg"', 'href="touch-icon.png"', 'href="team.html"']:
        h = h.replace(a, a.replace('="', '="../'))
    h = h.replace('<link rel="canonical" href="https://vibeforce.commandagi.app/">', f'<link rel="canonical" href="https://vibeforce.commandagi.app/{loc}/">')
    h = h.replace('<meta property="og:url" content="https://vibeforce.commandagi.app/">', f'<meta property="og:url" content="https://vibeforce.commandagi.app/{loc}/">')
    (SITE / loc / "index.html").write_text(h)
    print(loc, "written")
